BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"g":7,"sem":1,"n":1,"title":"الاستماع والتحدث — الفصل الأول","activity3":"speaking","skill":"الاستماع والحوار باحترام الأدلة","passage":"في مناقشة مدرسية حول الوقت المخصص للمكتبة، قالت ليلى إن فتح المكتبة مبكرًا يساعد الطلاب على الاستعارة. رد زميلها بأن نجاح الخطة يحتاج تنظيم الإشراف. المتحدث الجيد يعيد صياغة رأي الآخر قبل التعقيب، ويذكر السبب دون مقاطعة.","q1":"ما حجة ليلى في الحوار؟","a1":"تسهيل استعارة الكتب","w1":["زيادة الضوضاء","إلغاء التنظيم","ترك المكتبة مغلقة"],"q2":"ما التصرف الأنسب قبل الرد؟","a2":"تلخيص رأي الطرف الآخر بدقة","w2":["المقاطعة","تغيير الموضوع","الحكم على الشخص"],"practice":"قدّم دقيقة شفوية تذكر فيها رأيًا وحجة واعتراضًا مهذبًا. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 1."},{"g":7,"sem":1,"n":2,"title":"القراءة والفهم — الفصل الأول","activity3":"reading","skill":"قراءة فكرة رئيسة وتفصيل داعم","passage":"في فقرة مستقلة «أسس الطلاب مجموعة قراءة أسبوعية. اختاروا موضوعًا مشتركًا، وخصصوا عشر دقائق لتبادل الأسئلة. وبنهاية الشهر استطاع كل منهم تلخيص قصة». الفكرة هي تنظيم القراءة التعاونية، والتفاصيل توضّح خطواتها، ولا يصح استنتاج أثر على جميع المدارس.","q1":"ما الفكرة الأساسية في النص؟","a1":"تنظيم القراءة التعاونية","w1":["وصف الطقس","شراء الأجهزة","زيارة متحف"],"q2":"أي تفصيل مذكور حرفيًا؟","a2":"خصصوا عشر دقائق للأسئلة","w2":["سافروا خارج المدينة","استعاروا مئة كتاب","ألغوا الحصة"],"practice":"استخرج الفكرة الرئيسة ودليلين واستنتاجًا لا يثبته النص. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 1."},{"g":7,"sem":1,"n":3,"title":"الصنف اللغوي — الفصل الأول","activity3":"writing","skill":"الصنف اللغوي وتمييز اسم الفاعل","passage":"في «الكاتبُ يراجعُ مسودته» يمكن أن يكون «الكاتب» اسم فاعل من الفعل الثلاثي «كتب» على وزن فاعل، و«يراجع» فعل مضارع. يختلف اسم الفاعل عن الفاعل بوصفه وظيفة إعرابية؛ فلا يصح الخلط بين الصيغة الصرفية ودور الكلمة في الجملة.","q1":"ما الصيغة الصرفية لكلمة «كاتب»؟","a1":"اسم فاعل","w1":["حرف جر","فعل ماض","اسم إشارة"],"q2":"أي كلمة فعل مضارع في المثال؟","a2":"يراجع","w2":["الكاتب","مسودته","من"],"practice":"صغ أربعة أمثلة لأسماء فاعل وميّز الوزن من الإعراب في جملة. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 1."},{"g":7,"sem":1,"n":4,"title":"الوظيفة النحوية — الفصل الأول","activity3":"writing","skill":"الوظيفة النحوية للمبتدأ والخبر","passage":"في «الطلابُ منظمونَ» «الطلابُ» مبتدأ مرفوع بالضمة، و«منظمونَ» خبر مرفوع بالواو لأنه جمع مذكر سالم. أما «تنظّمَ الطلابُ» فيصير «الطلابُ» فاعلًا. يتعين الإعراب من تركيب الجملة لا من حفظ الكلمة وحدها.","q1":"ما إعراب «منظمون» في الجملة الاسمية؟","a1":"خبر مرفوع بالواو","w1":["مفعول به","فعل مضارع","اسم مجرور"],"q2":"ما إعراب «الطلاب» في «تنظم الطلاب»؟","a2":"فاعل مرفوع","w2":["مفعول به","خبر إن","حال"],"practice":"أعرب جملة اسمية وجملة فعلية مع بيان العلامة الإعرابية. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 1."},{"g":7,"sem":1,"n":5,"title":"الأسلوب اللغوي — الفصل الأول","activity3":"reading","skill":"الأسلوب اللغوي وفرق الاستفهام عن النهي","passage":"«هل انتهى الفريق من العمل؟» استفهام، و«لا تهملْ المراجعة» نهي بـ«لا» الناهية مع مضارع مجزوم. قد يخرج السؤال إلى غرض بلاغي وفق السياق، لكن لا نحكم عليه من شكل العلامة وحدها دون فهم المخاطب.","q1":"ما الأداة في «هل انتهى الفريق»؟","a1":"أداة استفهام","w1":["حرف نداء","أداة نهي","حرف جر"],"q2":"ما الغرض من «لا تهمل المراجعة»؟","a2":"النهي عن الإهمال","w2":["الاستفهام عن مكان","التعجب فقط","الإخبار عن الماضي"],"practice":"اكتب سؤالين ونهيين بأسلوب مهذب ثم اشرح موقع الأدوات. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 1."},{"g":7,"sem":1,"n":6,"title":"الظاهرة الإملائية — الفصل الأول","activity3":"writing","skill":"الظاهرة الإملائية والهمزة المتوسطة","passage":"ترسم الهمزة المتوسطة بالنظر إلى حركتها وحركة ما قبلها، مع مراعاة الحالات الخاصة؛ في «سُئِلَ» على نبرة لتأثير الكسرة، وفي «سَأَلَ» على ألف لمناسبة الفتحة. يعتمد التصحيح على ضبط الكلمة وعدم استبدال حرف لمجرد الشبه البصري.","q1":"على ماذا رسمت الهمزة في «سُئِل»؟","a1":"نبرة","w1":["واو","ألف","السطر"],"q2":"أي حركة أقوى في القاعدة العامة للهمزة المتوسطة؟","a2":"الكسرة","w2":["الفتحة","الضمة","السكون"],"practice":"اكتب ست كلمات مهموزة وفسّر كرسي الهمزة بالحركات. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 1."},{"g":7,"sem":1,"n":7,"title":"الرسم الكتابي — الفصل الأول","activity3":"writing","skill":"الرسم الكتابي والتنظيم البصري","passage":"تبدأ الكتابة الواضحة بتحديد اتجاه السطر والمسافات المناسبة بين الكلمات، والمحافظة على أحجام الحروف والتمييز بين النقاط. يجب أن تخدم علامات الترقيم فهم القارئ، لا أن تتحول إلى زينة. في مثال تدريبي تُراجع فقرة قصيرة وتحدد بداية الجمل ونهاياتها.","q1":"ما الذي يحسن قابلية قراءة الفقرة؟","a1":"مسافات مناسبة وعلامات ترقيم واضحة","w1":["وصل جميع الكلمات","حذف النقاط","ترك الجملة بلا نهاية"],"q2":"أين توضع النقطة غالبًا؟","a2":"في نهاية الجملة التامة","w2":["بعد كل حرف","وسط كل كلمة","بدل علامات التنوين"],"practice":"اكتب فقرة من أربعة أسطر بخط واضح وقارن تنظيمها قبل المراجعة وبعدها. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 1."},{"g":7,"sem":1,"n":8,"title":"التواصل الكتابي — الفصل الأول","activity3":"writing","skill":"التواصل الكتابي وبناء مقال قصير","passage":"يبدأ المقال بفكرة مركزية، ويتبعها تعليل وشاهد، ثم خاتمة تعيد النتيجة دون تكرار حرفي. في نموذج مستقل يرى كاتب أن القراءة اليومية تنمّي حصيلته اللغوية، ويذكر ملاحظته خلال شهر. لا يمكن تحويل ملاحظته الفردية إلى نسبة نجاح عامة بلا بحث.","q1":"ما الذي يقوي الفقرة الحجاجية؟","a1":"سبب واضح ومثال ملائم","w1":["تكرار الادعاء فقط","إلغاء الشاهد","استعمال كلمات كثيرة بلا معنى"],"q2":"ما الجملة المناسبة في خاتمة المقال؟","a2":"نتيجة متصلة بالحجة","w2":["موضوع جديد بلا صلة","اسم الكاتب فقط","عنوان مختلف"],"practice":"اكتب مقالًا من ثلاث فقرات حول عادة دراسية مع حجة وتحفظ وخاتمة. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 1."},{"g":7,"sem":2,"n":1,"title":"الاستماع والتحدث — الفصل الثاني","activity3":"speaking","skill":"إدارة حوار شفهي ومقارنة حجتين","passage":"اقترحت مريم إقامة معرض لأعمال الطلاب، وذكرت أنه يظهر مهاراتهم؛ بينما اقترح عمر أن يبدأ المعرض بحجم صغير لتجربة التنظيم. يمكن الجمع بين الرأيين في معرض تجريبي له معايير واضحة، بشرط عرض وجهتي النظر دون تشويه.","q1":"ما المقترح الذي يستجيب للرأيين؟","a1":"معرض تجريبي بمعايير معلنة","w1":["إلغاء المشروع دون نقاش","تنفيذ بلا تنظيم","تجاهل أحد الرأيين"],"q2":"ما مهارة الحوار الأساسية هنا؟","a2":"الموازنة بين الحجج","w2":["المقاطعة","التعميم","إخفاء المقترح"],"practice":"سجل مناقشة قصيرة تقارن حلين ثم اختر أحدهما بسبب صريح. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 2."},{"g":7,"sem":2,"n":2,"title":"القراءة والفهم — الفصل الثاني","activity3":"reading","skill":"القراءة التحليلية والتمييز بين حقيقة ورأي","passage":"«زار فريق المدرسة ثلاثة مراكز علمية خلال أسبوع» معلومة قابلة للتحقق داخل نص التدريب، أما «كانت الزيارة أجمل تجربة في العالم» فهي حكم شخصي. لا يقبل التحليل الجيد الاستنتاجات التي تتجاوز النص. نحدد صياغة الدليل ونقارنها بموقف الراوي.","q1":"أي جملة تحمل حكمًا ذاتيًا؟","a1":"كانت أجمل تجربة في العالم","w1":["زار الفريق ثلاثة مراكز","استمرت الزيارة أسبوعًا","كان الفريق من المدرسة"],"q2":"أي جملة أكثر قابلية للتحقق؟","a2":"زار الفريق ثلاثة مراكز","w2":["كل زيارة رائعة","الجميع سعداء دائمًا","لا يمكن نقد التجربة"],"practice":"صنف ست عبارات من فقرة إلى معلومات وآراء مع قرائن التصنيف. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 2."},{"g":7,"sem":2,"n":3,"title":"الصنف اللغوي — الفصل الثاني","activity3":"writing","skill":"الصنف اللغوي واسم المفعول","passage":"«مكتوب» اسم مفعول من «كتب»، ويشير إلى ما وقع عليه الفعل، بخلاف «كاتب» الذي يدل على من قام بالكتابة. يمكن أن تتغير الصيغة الصرفية باختلاف نوع الفعل؛ ويفسر الطالب دور المعنى والوزن بدل حفظ قائمة معزولة.","q1":"أي كلمة اسم مفعول؟","a1":"مكتوب","w1":["كاتب","يكتب","اكتب"],"q2":"أي كلمة تدل على من قام بالكتابة؟","a2":"كاتب","w2":["مكتوب","كتابان","من"],"practice":"أنشئ أمثلة لأسماء فاعل ومفعول في جمل صحيحة ثم بيّن الفرق الدلالي. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 2."},{"g":7,"sem":2,"n":4,"title":"الوظيفة النحوية — الفصل الثاني","activity3":"writing","skill":"الوظيفة النحوية والتمييز بين الحال والنعت","passage":"في «عاد المسافرُ مسرورًا» «مسرورًا» حال منصوب يبين هيئة المسافر عند العودة، أما «المسافرُ المسرورُ عاد» ففيه «المسرورُ» نعت يتبع المنعوت في التعريف والإعراب. يتغير التحليل بتغير تركيب الجملة.","q1":"ما إعراب «مسرورًا» في المثال الأول؟","a1":"حال منصوب","w1":["مبتدأ","فاعل","خبر إن"],"q2":"ما وظيفة «المسرور» في المثال الثاني؟","a2":"نعت مرفوع","w2":["مفعول به","حال منصوب","حرف جر"],"practice":"اكتب جملتين للحال وأخريين للنعت واشرح الفروق. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 2."},{"g":7,"sem":2,"n":5,"title":"الأسلوب اللغوي — الفصل الثاني","activity3":"reading","skill":"الأسلوب اللغوي والتمني والترجي","passage":"«ليتَ الوقتَ يتسعُ» تمني بـ«ليت»، و«لعلَّ المطرَ ينزلُ» ترجٍّ بحسب مقامه؛ يتغير معنى الأسلوب من رغبة بعيدة أو محتملة إلى توقع مرجو. ينبغي ضبط اسم الناسخ وإيضاح غرض التعبير دون الخلط بين الأسلوبين.","q1":"ما الأداة التي تفيد التمني في المثال؟","a1":"ليت","w1":["من","في","أين"],"q2":"ما الأداة التي تفيد الترجي؟","a2":"لعل","w2":["لم","هل","لن"],"practice":"أنشئ أربع جمل للتمني والترجي وفسر تغير الدلالة حسب المقام. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 2."},{"g":7,"sem":2,"n":6,"title":"الظاهرة الإملائية — الفصل الثاني","activity3":"writing","skill":"الظاهرة الإملائية والتنوين والألف الفارقة","passage":"في «كتبوا» تأتي ألف فارقة بعد واو الجماعة في الفعل الماضي، لكنها لا تضاف إلى واو جمع المذكر السالم في «معلمو المدرسة». و«كتابًا» يحمل تنوين الفتح وفق موضع الألف في الكتابة، مع مراعاة حالات خاصة.","q1":"أين تظهر الألف الفارقة؟","a1":"بعد واو الجماعة في «كتبوا»","w1":["بعد الواو في «معلمو»","في كل جمع","بعد كل ميم"],"q2":"أي تركيب لا تُزاد فيه الألف الفارقة؟","a2":"معلمو المدرسة","w2":["ذهبوا","كتبوا","راجعوا"],"practice":"اكتب أفعالًا مع واو الجماعة وأسماء مضافة تنتهي بالواو ثم فرق الرسم. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 2."},{"g":7,"sem":2,"n":7,"title":"الرسم الكتابي — الفصل الثاني","activity3":"writing","skill":"الرسم الكتابي وضبط علامات الترقيم","passage":"تُستخدم الفاصلة بين أجزاء مترابطة من الجملة، وتوضع علامة الاستفهام بعد السؤال، والفاصلة المنقوطة قد تربط جملتين بينهما علاقة سببية. لا تكفي كثرة العلامات لتحسين النص إذا كانت لا توافق المعنى.","q1":"ما علامة نهاية سؤال مباشر؟","a1":"علامة الاستفهام","w1":["علامة التعجب دائمًا","الفاصلة","النقطتان"],"q2":"لماذا تستخدم الفاصلة المنقوطة في موضع مناسب؟","a2":"لربط جملتين بينهما صلة قوية","w2":["لإلغاء الفعل","لكتابة همزة","لإنهاء كل كلمة"],"practice":"أعد ترقيم فقرة غير مضبوطة وعلل ثلاثة مواضع للاختيار. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 2."},{"g":7,"sem":2,"n":8,"title":"التواصل الكتابي — الفصل الثاني","activity3":"writing","skill":"التواصل الكتابي وتحرير رسالة رسمية","passage":"تتكون الرسالة الرسمية من جهة مخاطبة وموضوع وطلب واضح وسبب مختصر وخاتمة مهذبة. في نموذج مستقل يطلب طالب تخصيص قاعة للمراجعة ويذكر الوقت وطريقة الاستخدام المقترحة، دون إضافة معلومات خاصة لا يحتاجها الطلب.","q1":"ما العنصر الضروري في خطاب الطلب؟","a1":"المطلوب المحدد وسببه","w1":["قصيدة طويلة","الاعتذار بلا موضوع","حذف الموعد"],"q2":"أي معلومة تفيد إدارة القاعة؟","a2":"الوقت المقترح وطريقة الاستخدام","w2":["أسرار الزملاء","عدد الرسائل الشخصية","معلومات لا علاقة لها"],"practice":"اكتب رسالة رسمية من عشرة أسطر حول مشروع مدرسي وراجع النبرة والدقة. في الصف 7 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 7، مستوى تحليلي متدرج، الفصل 2."},{"g":8,"sem":1,"n":1,"title":"الاستماع والتحدث — الفصل الأول","activity3":"speaking","skill":"الاستماع والحوار باحترام الأدلة","passage":"في مناقشة مدرسية حول الوقت المخصص للمكتبة، قالت ليلى إن فتح المكتبة مبكرًا يساعد الطلاب على الاستعارة. رد زميلها بأن نجاح الخطة يحتاج تنظيم الإشراف. المتحدث الجيد يعيد صياغة رأي الآخر قبل التعقيب، ويذكر السبب دون مقاطعة.","q1":"ما حجة ليلى في الحوار؟","a1":"تسهيل استعارة الكتب","w1":["زيادة الضوضاء","إلغاء التنظيم","ترك المكتبة مغلقة"],"q2":"ما التصرف الأنسب قبل الرد؟","a2":"تلخيص رأي الطرف الآخر بدقة","w2":["المقاطعة","تغيير الموضوع","الحكم على الشخص"],"practice":"قدّم دقيقة شفوية تذكر فيها رأيًا وحجة واعتراضًا مهذبًا. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 1."},{"g":8,"sem":1,"n":2,"title":"القراءة والفهم — الفصل الأول","activity3":"reading","skill":"قراءة فكرة رئيسة وتفصيل داعم","passage":"في فقرة مستقلة «أسس الطلاب مجموعة قراءة أسبوعية. اختاروا موضوعًا مشتركًا، وخصصوا عشر دقائق لتبادل الأسئلة. وبنهاية الشهر استطاع كل منهم تلخيص قصة». الفكرة هي تنظيم القراءة التعاونية، والتفاصيل توضّح خطواتها، ولا يصح استنتاج أثر على جميع المدارس.","q1":"ما الفكرة الأساسية في النص؟","a1":"تنظيم القراءة التعاونية","w1":["وصف الطقس","شراء الأجهزة","زيارة متحف"],"q2":"أي تفصيل مذكور حرفيًا؟","a2":"خصصوا عشر دقائق للأسئلة","w2":["سافروا خارج المدينة","استعاروا مئة كتاب","ألغوا الحصة"],"practice":"استخرج الفكرة الرئيسة ودليلين واستنتاجًا لا يثبته النص. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 1."},{"g":8,"sem":1,"n":3,"title":"الصنف اللغوي — الفصل الأول","activity3":"writing","skill":"الصنف اللغوي وتمييز اسم الفاعل","passage":"في «الكاتبُ يراجعُ مسودته» يمكن أن يكون «الكاتب» اسم فاعل من الفعل الثلاثي «كتب» على وزن فاعل، و«يراجع» فعل مضارع. يختلف اسم الفاعل عن الفاعل بوصفه وظيفة إعرابية؛ فلا يصح الخلط بين الصيغة الصرفية ودور الكلمة في الجملة.","q1":"ما الصيغة الصرفية لكلمة «كاتب»؟","a1":"اسم فاعل","w1":["حرف جر","فعل ماض","اسم إشارة"],"q2":"أي كلمة فعل مضارع في المثال؟","a2":"يراجع","w2":["الكاتب","مسودته","من"],"practice":"صغ أربعة أمثلة لأسماء فاعل وميّز الوزن من الإعراب في جملة. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 1."},{"g":8,"sem":1,"n":4,"title":"الوظيفة النحوية — الفصل الأول","activity3":"writing","skill":"الوظيفة النحوية للمبتدأ والخبر","passage":"في «الطلابُ منظمونَ» «الطلابُ» مبتدأ مرفوع بالضمة، و«منظمونَ» خبر مرفوع بالواو لأنه جمع مذكر سالم. أما «تنظّمَ الطلابُ» فيصير «الطلابُ» فاعلًا. يتعين الإعراب من تركيب الجملة لا من حفظ الكلمة وحدها.","q1":"ما إعراب «منظمون» في الجملة الاسمية؟","a1":"خبر مرفوع بالواو","w1":["مفعول به","فعل مضارع","اسم مجرور"],"q2":"ما إعراب «الطلاب» في «تنظم الطلاب»؟","a2":"فاعل مرفوع","w2":["مفعول به","خبر إن","حال"],"practice":"أعرب جملة اسمية وجملة فعلية مع بيان العلامة الإعرابية. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 1."},{"g":8,"sem":1,"n":5,"title":"الأسلوب اللغوي — الفصل الأول","activity3":"reading","skill":"الأسلوب اللغوي وفرق الاستفهام عن النهي","passage":"«هل انتهى الفريق من العمل؟» استفهام، و«لا تهملْ المراجعة» نهي بـ«لا» الناهية مع مضارع مجزوم. قد يخرج السؤال إلى غرض بلاغي وفق السياق، لكن لا نحكم عليه من شكل العلامة وحدها دون فهم المخاطب.","q1":"ما الأداة في «هل انتهى الفريق»؟","a1":"أداة استفهام","w1":["حرف نداء","أداة نهي","حرف جر"],"q2":"ما الغرض من «لا تهمل المراجعة»؟","a2":"النهي عن الإهمال","w2":["الاستفهام عن مكان","التعجب فقط","الإخبار عن الماضي"],"practice":"اكتب سؤالين ونهيين بأسلوب مهذب ثم اشرح موقع الأدوات. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 1."},{"g":8,"sem":1,"n":6,"title":"الظاهرة الإملائية — الفصل الأول","activity3":"writing","skill":"الظاهرة الإملائية والهمزة المتوسطة","passage":"ترسم الهمزة المتوسطة بالنظر إلى حركتها وحركة ما قبلها، مع مراعاة الحالات الخاصة؛ في «سُئِلَ» على نبرة لتأثير الكسرة، وفي «سَأَلَ» على ألف لمناسبة الفتحة. يعتمد التصحيح على ضبط الكلمة وعدم استبدال حرف لمجرد الشبه البصري.","q1":"على ماذا رسمت الهمزة في «سُئِل»؟","a1":"نبرة","w1":["واو","ألف","السطر"],"q2":"أي حركة أقوى في القاعدة العامة للهمزة المتوسطة؟","a2":"الكسرة","w2":["الفتحة","الضمة","السكون"],"practice":"اكتب ست كلمات مهموزة وفسّر كرسي الهمزة بالحركات. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 1."},{"g":8,"sem":1,"n":7,"title":"الرسم الكتابي — الفصل الأول","activity3":"writing","skill":"الرسم الكتابي والتنظيم البصري","passage":"تبدأ الكتابة الواضحة بتحديد اتجاه السطر والمسافات المناسبة بين الكلمات، والمحافظة على أحجام الحروف والتمييز بين النقاط. يجب أن تخدم علامات الترقيم فهم القارئ، لا أن تتحول إلى زينة. في مثال تدريبي تُراجع فقرة قصيرة وتحدد بداية الجمل ونهاياتها.","q1":"ما الذي يحسن قابلية قراءة الفقرة؟","a1":"مسافات مناسبة وعلامات ترقيم واضحة","w1":["وصل جميع الكلمات","حذف النقاط","ترك الجملة بلا نهاية"],"q2":"أين توضع النقطة غالبًا؟","a2":"في نهاية الجملة التامة","w2":["بعد كل حرف","وسط كل كلمة","بدل علامات التنوين"],"practice":"اكتب فقرة من أربعة أسطر بخط واضح وقارن تنظيمها قبل المراجعة وبعدها. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 1."},{"g":8,"sem":1,"n":8,"title":"التواصل الكتابي — الفصل الأول","activity3":"writing","skill":"التواصل الكتابي وبناء مقال قصير","passage":"يبدأ المقال بفكرة مركزية، ويتبعها تعليل وشاهد، ثم خاتمة تعيد النتيجة دون تكرار حرفي. في نموذج مستقل يرى كاتب أن القراءة اليومية تنمّي حصيلته اللغوية، ويذكر ملاحظته خلال شهر. لا يمكن تحويل ملاحظته الفردية إلى نسبة نجاح عامة بلا بحث.","q1":"ما الذي يقوي الفقرة الحجاجية؟","a1":"سبب واضح ومثال ملائم","w1":["تكرار الادعاء فقط","إلغاء الشاهد","استعمال كلمات كثيرة بلا معنى"],"q2":"ما الجملة المناسبة في خاتمة المقال؟","a2":"نتيجة متصلة بالحجة","w2":["موضوع جديد بلا صلة","اسم الكاتب فقط","عنوان مختلف"],"practice":"اكتب مقالًا من ثلاث فقرات حول عادة دراسية مع حجة وتحفظ وخاتمة. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 1."},{"g":8,"sem":2,"n":1,"title":"الاستماع والتحدث — الفصل الثاني","activity3":"speaking","skill":"إدارة حوار شفهي ومقارنة حجتين","passage":"اقترحت مريم إقامة معرض لأعمال الطلاب، وذكرت أنه يظهر مهاراتهم؛ بينما اقترح عمر أن يبدأ المعرض بحجم صغير لتجربة التنظيم. يمكن الجمع بين الرأيين في معرض تجريبي له معايير واضحة، بشرط عرض وجهتي النظر دون تشويه.","q1":"ما المقترح الذي يستجيب للرأيين؟","a1":"معرض تجريبي بمعايير معلنة","w1":["إلغاء المشروع دون نقاش","تنفيذ بلا تنظيم","تجاهل أحد الرأيين"],"q2":"ما مهارة الحوار الأساسية هنا؟","a2":"الموازنة بين الحجج","w2":["المقاطعة","التعميم","إخفاء المقترح"],"practice":"سجل مناقشة قصيرة تقارن حلين ثم اختر أحدهما بسبب صريح. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 2."},{"g":8,"sem":2,"n":2,"title":"القراءة والفهم — الفصل الثاني","activity3":"reading","skill":"القراءة التحليلية والتمييز بين حقيقة ورأي","passage":"«زار فريق المدرسة ثلاثة مراكز علمية خلال أسبوع» معلومة قابلة للتحقق داخل نص التدريب، أما «كانت الزيارة أجمل تجربة في العالم» فهي حكم شخصي. لا يقبل التحليل الجيد الاستنتاجات التي تتجاوز النص. نحدد صياغة الدليل ونقارنها بموقف الراوي.","q1":"أي جملة تحمل حكمًا ذاتيًا؟","a1":"كانت أجمل تجربة في العالم","w1":["زار الفريق ثلاثة مراكز","استمرت الزيارة أسبوعًا","كان الفريق من المدرسة"],"q2":"أي جملة أكثر قابلية للتحقق؟","a2":"زار الفريق ثلاثة مراكز","w2":["كل زيارة رائعة","الجميع سعداء دائمًا","لا يمكن نقد التجربة"],"practice":"صنف ست عبارات من فقرة إلى معلومات وآراء مع قرائن التصنيف. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 2."},{"g":8,"sem":2,"n":3,"title":"الصنف اللغوي — الفصل الثاني","activity3":"writing","skill":"الصنف اللغوي واسم المفعول","passage":"«مكتوب» اسم مفعول من «كتب»، ويشير إلى ما وقع عليه الفعل، بخلاف «كاتب» الذي يدل على من قام بالكتابة. يمكن أن تتغير الصيغة الصرفية باختلاف نوع الفعل؛ ويفسر الطالب دور المعنى والوزن بدل حفظ قائمة معزولة.","q1":"أي كلمة اسم مفعول؟","a1":"مكتوب","w1":["كاتب","يكتب","اكتب"],"q2":"أي كلمة تدل على من قام بالكتابة؟","a2":"كاتب","w2":["مكتوب","كتابان","من"],"practice":"أنشئ أمثلة لأسماء فاعل ومفعول في جمل صحيحة ثم بيّن الفرق الدلالي. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 2."},{"g":8,"sem":2,"n":4,"title":"الوظيفة النحوية — الفصل الثاني","activity3":"writing","skill":"الوظيفة النحوية والتمييز بين الحال والنعت","passage":"في «عاد المسافرُ مسرورًا» «مسرورًا» حال منصوب يبين هيئة المسافر عند العودة، أما «المسافرُ المسرورُ عاد» ففيه «المسرورُ» نعت يتبع المنعوت في التعريف والإعراب. يتغير التحليل بتغير تركيب الجملة.","q1":"ما إعراب «مسرورًا» في المثال الأول؟","a1":"حال منصوب","w1":["مبتدأ","فاعل","خبر إن"],"q2":"ما وظيفة «المسرور» في المثال الثاني؟","a2":"نعت مرفوع","w2":["مفعول به","حال منصوب","حرف جر"],"practice":"اكتب جملتين للحال وأخريين للنعت واشرح الفروق. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 2."},{"g":8,"sem":2,"n":5,"title":"الأسلوب اللغوي — الفصل الثاني","activity3":"reading","skill":"الأسلوب اللغوي والتمني والترجي","passage":"«ليتَ الوقتَ يتسعُ» تمني بـ«ليت»، و«لعلَّ المطرَ ينزلُ» ترجٍّ بحسب مقامه؛ يتغير معنى الأسلوب من رغبة بعيدة أو محتملة إلى توقع مرجو. ينبغي ضبط اسم الناسخ وإيضاح غرض التعبير دون الخلط بين الأسلوبين.","q1":"ما الأداة التي تفيد التمني في المثال؟","a1":"ليت","w1":["من","في","أين"],"q2":"ما الأداة التي تفيد الترجي؟","a2":"لعل","w2":["لم","هل","لن"],"practice":"أنشئ أربع جمل للتمني والترجي وفسر تغير الدلالة حسب المقام. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 2."},{"g":8,"sem":2,"n":6,"title":"الظاهرة الإملائية — الفصل الثاني","activity3":"writing","skill":"الظاهرة الإملائية والتنوين والألف الفارقة","passage":"في «كتبوا» تأتي ألف فارقة بعد واو الجماعة في الفعل الماضي، لكنها لا تضاف إلى واو جمع المذكر السالم في «معلمو المدرسة». و«كتابًا» يحمل تنوين الفتح وفق موضع الألف في الكتابة، مع مراعاة حالات خاصة.","q1":"أين تظهر الألف الفارقة؟","a1":"بعد واو الجماعة في «كتبوا»","w1":["بعد الواو في «معلمو»","في كل جمع","بعد كل ميم"],"q2":"أي تركيب لا تُزاد فيه الألف الفارقة؟","a2":"معلمو المدرسة","w2":["ذهبوا","كتبوا","راجعوا"],"practice":"اكتب أفعالًا مع واو الجماعة وأسماء مضافة تنتهي بالواو ثم فرق الرسم. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 2."},{"g":8,"sem":2,"n":7,"title":"الرسم الكتابي — الفصل الثاني","activity3":"writing","skill":"الرسم الكتابي وضبط علامات الترقيم","passage":"تُستخدم الفاصلة بين أجزاء مترابطة من الجملة، وتوضع علامة الاستفهام بعد السؤال، والفاصلة المنقوطة قد تربط جملتين بينهما علاقة سببية. لا تكفي كثرة العلامات لتحسين النص إذا كانت لا توافق المعنى.","q1":"ما علامة نهاية سؤال مباشر؟","a1":"علامة الاستفهام","w1":["علامة التعجب دائمًا","الفاصلة","النقطتان"],"q2":"لماذا تستخدم الفاصلة المنقوطة في موضع مناسب؟","a2":"لربط جملتين بينهما صلة قوية","w2":["لإلغاء الفعل","لكتابة همزة","لإنهاء كل كلمة"],"practice":"أعد ترقيم فقرة غير مضبوطة وعلل ثلاثة مواضع للاختيار. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 2."},{"g":8,"sem":2,"n":8,"title":"التواصل الكتابي — الفصل الثاني","activity3":"writing","skill":"التواصل الكتابي وتحرير رسالة رسمية","passage":"تتكون الرسالة الرسمية من جهة مخاطبة وموضوع وطلب واضح وسبب مختصر وخاتمة مهذبة. في نموذج مستقل يطلب طالب تخصيص قاعة للمراجعة ويذكر الوقت وطريقة الاستخدام المقترحة، دون إضافة معلومات خاصة لا يحتاجها الطلب.","q1":"ما العنصر الضروري في خطاب الطلب؟","a1":"المطلوب المحدد وسببه","w1":["قصيدة طويلة","الاعتذار بلا موضوع","حذف الموعد"],"q2":"أي معلومة تفيد إدارة القاعة؟","a2":"الوقت المقترح وطريقة الاستخدام","w2":["أسرار الزملاء","عدد الرسائل الشخصية","معلومات لا علاقة لها"],"practice":"اكتب رسالة رسمية من عشرة أسطر حول مشروع مدرسي وراجع النبرة والدقة. في الصف 8 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 8، مستوى تحليلي متدرج، الفصل 2."},{"g":9,"sem":1,"n":1,"title":"الاستماع والتحدث — الفصل الأول","activity3":"speaking","skill":"الاستماع والحوار باحترام الأدلة","passage":"في مناقشة مدرسية حول الوقت المخصص للمكتبة، قالت ليلى إن فتح المكتبة مبكرًا يساعد الطلاب على الاستعارة. رد زميلها بأن نجاح الخطة يحتاج تنظيم الإشراف. المتحدث الجيد يعيد صياغة رأي الآخر قبل التعقيب، ويذكر السبب دون مقاطعة.","q1":"ما حجة ليلى في الحوار؟","a1":"تسهيل استعارة الكتب","w1":["زيادة الضوضاء","إلغاء التنظيم","ترك المكتبة مغلقة"],"q2":"ما التصرف الأنسب قبل الرد؟","a2":"تلخيص رأي الطرف الآخر بدقة","w2":["المقاطعة","تغيير الموضوع","الحكم على الشخص"],"practice":"قدّم دقيقة شفوية تذكر فيها رأيًا وحجة واعتراضًا مهذبًا. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 1."},{"g":9,"sem":1,"n":2,"title":"القراءة والفهم — الفصل الأول","activity3":"reading","skill":"قراءة فكرة رئيسة وتفصيل داعم","passage":"في فقرة مستقلة «أسس الطلاب مجموعة قراءة أسبوعية. اختاروا موضوعًا مشتركًا، وخصصوا عشر دقائق لتبادل الأسئلة. وبنهاية الشهر استطاع كل منهم تلخيص قصة». الفكرة هي تنظيم القراءة التعاونية، والتفاصيل توضّح خطواتها، ولا يصح استنتاج أثر على جميع المدارس.","q1":"ما الفكرة الأساسية في النص؟","a1":"تنظيم القراءة التعاونية","w1":["وصف الطقس","شراء الأجهزة","زيارة متحف"],"q2":"أي تفصيل مذكور حرفيًا؟","a2":"خصصوا عشر دقائق للأسئلة","w2":["سافروا خارج المدينة","استعاروا مئة كتاب","ألغوا الحصة"],"practice":"استخرج الفكرة الرئيسة ودليلين واستنتاجًا لا يثبته النص. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 1."},{"g":9,"sem":1,"n":3,"title":"الصنف اللغوي — الفصل الأول","activity3":"writing","skill":"الصنف اللغوي وتمييز اسم الفاعل","passage":"في «الكاتبُ يراجعُ مسودته» يمكن أن يكون «الكاتب» اسم فاعل من الفعل الثلاثي «كتب» على وزن فاعل، و«يراجع» فعل مضارع. يختلف اسم الفاعل عن الفاعل بوصفه وظيفة إعرابية؛ فلا يصح الخلط بين الصيغة الصرفية ودور الكلمة في الجملة.","q1":"ما الصيغة الصرفية لكلمة «كاتب»؟","a1":"اسم فاعل","w1":["حرف جر","فعل ماض","اسم إشارة"],"q2":"أي كلمة فعل مضارع في المثال؟","a2":"يراجع","w2":["الكاتب","مسودته","من"],"practice":"صغ أربعة أمثلة لأسماء فاعل وميّز الوزن من الإعراب في جملة. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 1."},{"g":9,"sem":1,"n":4,"title":"الوظيفة النحوية — الفصل الأول","activity3":"writing","skill":"الوظيفة النحوية للمبتدأ والخبر","passage":"في «الطلابُ منظمونَ» «الطلابُ» مبتدأ مرفوع بالضمة، و«منظمونَ» خبر مرفوع بالواو لأنه جمع مذكر سالم. أما «تنظّمَ الطلابُ» فيصير «الطلابُ» فاعلًا. يتعين الإعراب من تركيب الجملة لا من حفظ الكلمة وحدها.","q1":"ما إعراب «منظمون» في الجملة الاسمية؟","a1":"خبر مرفوع بالواو","w1":["مفعول به","فعل مضارع","اسم مجرور"],"q2":"ما إعراب «الطلاب» في «تنظم الطلاب»؟","a2":"فاعل مرفوع","w2":["مفعول به","خبر إن","حال"],"practice":"أعرب جملة اسمية وجملة فعلية مع بيان العلامة الإعرابية. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 1."},{"g":9,"sem":1,"n":5,"title":"الأسلوب اللغوي — الفصل الأول","activity3":"reading","skill":"الأسلوب اللغوي وفرق الاستفهام عن النهي","passage":"«هل انتهى الفريق من العمل؟» استفهام، و«لا تهملْ المراجعة» نهي بـ«لا» الناهية مع مضارع مجزوم. قد يخرج السؤال إلى غرض بلاغي وفق السياق، لكن لا نحكم عليه من شكل العلامة وحدها دون فهم المخاطب.","q1":"ما الأداة في «هل انتهى الفريق»؟","a1":"أداة استفهام","w1":["حرف نداء","أداة نهي","حرف جر"],"q2":"ما الغرض من «لا تهمل المراجعة»؟","a2":"النهي عن الإهمال","w2":["الاستفهام عن مكان","التعجب فقط","الإخبار عن الماضي"],"practice":"اكتب سؤالين ونهيين بأسلوب مهذب ثم اشرح موقع الأدوات. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 1."},{"g":9,"sem":1,"n":6,"title":"الظاهرة الإملائية — الفصل الأول","activity3":"writing","skill":"الظاهرة الإملائية والهمزة المتوسطة","passage":"ترسم الهمزة المتوسطة بالنظر إلى حركتها وحركة ما قبلها، مع مراعاة الحالات الخاصة؛ في «سُئِلَ» على نبرة لتأثير الكسرة، وفي «سَأَلَ» على ألف لمناسبة الفتحة. يعتمد التصحيح على ضبط الكلمة وعدم استبدال حرف لمجرد الشبه البصري.","q1":"على ماذا رسمت الهمزة في «سُئِل»؟","a1":"نبرة","w1":["واو","ألف","السطر"],"q2":"أي حركة أقوى في القاعدة العامة للهمزة المتوسطة؟","a2":"الكسرة","w2":["الفتحة","الضمة","السكون"],"practice":"اكتب ست كلمات مهموزة وفسّر كرسي الهمزة بالحركات. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 1."},{"g":9,"sem":1,"n":7,"title":"الرسم الكتابي — الفصل الأول","activity3":"writing","skill":"الرسم الكتابي والتنظيم البصري","passage":"تبدأ الكتابة الواضحة بتحديد اتجاه السطر والمسافات المناسبة بين الكلمات، والمحافظة على أحجام الحروف والتمييز بين النقاط. يجب أن تخدم علامات الترقيم فهم القارئ، لا أن تتحول إلى زينة. في مثال تدريبي تُراجع فقرة قصيرة وتحدد بداية الجمل ونهاياتها.","q1":"ما الذي يحسن قابلية قراءة الفقرة؟","a1":"مسافات مناسبة وعلامات ترقيم واضحة","w1":["وصل جميع الكلمات","حذف النقاط","ترك الجملة بلا نهاية"],"q2":"أين توضع النقطة غالبًا؟","a2":"في نهاية الجملة التامة","w2":["بعد كل حرف","وسط كل كلمة","بدل علامات التنوين"],"practice":"اكتب فقرة من أربعة أسطر بخط واضح وقارن تنظيمها قبل المراجعة وبعدها. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 1."},{"g":9,"sem":1,"n":8,"title":"التواصل الكتابي — الفصل الأول","activity3":"writing","skill":"التواصل الكتابي وبناء مقال قصير","passage":"يبدأ المقال بفكرة مركزية، ويتبعها تعليل وشاهد، ثم خاتمة تعيد النتيجة دون تكرار حرفي. في نموذج مستقل يرى كاتب أن القراءة اليومية تنمّي حصيلته اللغوية، ويذكر ملاحظته خلال شهر. لا يمكن تحويل ملاحظته الفردية إلى نسبة نجاح عامة بلا بحث.","q1":"ما الذي يقوي الفقرة الحجاجية؟","a1":"سبب واضح ومثال ملائم","w1":["تكرار الادعاء فقط","إلغاء الشاهد","استعمال كلمات كثيرة بلا معنى"],"q2":"ما الجملة المناسبة في خاتمة المقال؟","a2":"نتيجة متصلة بالحجة","w2":["موضوع جديد بلا صلة","اسم الكاتب فقط","عنوان مختلف"],"practice":"اكتب مقالًا من ثلاث فقرات حول عادة دراسية مع حجة وتحفظ وخاتمة. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 1."},{"g":9,"sem":2,"n":1,"title":"الاستماع والتحدث — الفصل الثاني","activity3":"speaking","skill":"إدارة حوار شفهي ومقارنة حجتين","passage":"اقترحت مريم إقامة معرض لأعمال الطلاب، وذكرت أنه يظهر مهاراتهم؛ بينما اقترح عمر أن يبدأ المعرض بحجم صغير لتجربة التنظيم. يمكن الجمع بين الرأيين في معرض تجريبي له معايير واضحة، بشرط عرض وجهتي النظر دون تشويه.","q1":"ما المقترح الذي يستجيب للرأيين؟","a1":"معرض تجريبي بمعايير معلنة","w1":["إلغاء المشروع دون نقاش","تنفيذ بلا تنظيم","تجاهل أحد الرأيين"],"q2":"ما مهارة الحوار الأساسية هنا؟","a2":"الموازنة بين الحجج","w2":["المقاطعة","التعميم","إخفاء المقترح"],"practice":"سجل مناقشة قصيرة تقارن حلين ثم اختر أحدهما بسبب صريح. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 2."},{"g":9,"sem":2,"n":2,"title":"القراءة والفهم — الفصل الثاني","activity3":"reading","skill":"القراءة التحليلية والتمييز بين حقيقة ورأي","passage":"«زار فريق المدرسة ثلاثة مراكز علمية خلال أسبوع» معلومة قابلة للتحقق داخل نص التدريب، أما «كانت الزيارة أجمل تجربة في العالم» فهي حكم شخصي. لا يقبل التحليل الجيد الاستنتاجات التي تتجاوز النص. نحدد صياغة الدليل ونقارنها بموقف الراوي.","q1":"أي جملة تحمل حكمًا ذاتيًا؟","a1":"كانت أجمل تجربة في العالم","w1":["زار الفريق ثلاثة مراكز","استمرت الزيارة أسبوعًا","كان الفريق من المدرسة"],"q2":"أي جملة أكثر قابلية للتحقق؟","a2":"زار الفريق ثلاثة مراكز","w2":["كل زيارة رائعة","الجميع سعداء دائمًا","لا يمكن نقد التجربة"],"practice":"صنف ست عبارات من فقرة إلى معلومات وآراء مع قرائن التصنيف. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 2."},{"g":9,"sem":2,"n":3,"title":"الصنف اللغوي — الفصل الثاني","activity3":"writing","skill":"الصنف اللغوي واسم المفعول","passage":"«مكتوب» اسم مفعول من «كتب»، ويشير إلى ما وقع عليه الفعل، بخلاف «كاتب» الذي يدل على من قام بالكتابة. يمكن أن تتغير الصيغة الصرفية باختلاف نوع الفعل؛ ويفسر الطالب دور المعنى والوزن بدل حفظ قائمة معزولة.","q1":"أي كلمة اسم مفعول؟","a1":"مكتوب","w1":["كاتب","يكتب","اكتب"],"q2":"أي كلمة تدل على من قام بالكتابة؟","a2":"كاتب","w2":["مكتوب","كتابان","من"],"practice":"أنشئ أمثلة لأسماء فاعل ومفعول في جمل صحيحة ثم بيّن الفرق الدلالي. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 2."},{"g":9,"sem":2,"n":4,"title":"الوظيفة النحوية — الفصل الثاني","activity3":"writing","skill":"الوظيفة النحوية والتمييز بين الحال والنعت","passage":"في «عاد المسافرُ مسرورًا» «مسرورًا» حال منصوب يبين هيئة المسافر عند العودة، أما «المسافرُ المسرورُ عاد» ففيه «المسرورُ» نعت يتبع المنعوت في التعريف والإعراب. يتغير التحليل بتغير تركيب الجملة.","q1":"ما إعراب «مسرورًا» في المثال الأول؟","a1":"حال منصوب","w1":["مبتدأ","فاعل","خبر إن"],"q2":"ما وظيفة «المسرور» في المثال الثاني؟","a2":"نعت مرفوع","w2":["مفعول به","حال منصوب","حرف جر"],"practice":"اكتب جملتين للحال وأخريين للنعت واشرح الفروق. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 2."},{"g":9,"sem":2,"n":5,"title":"الأسلوب اللغوي — الفصل الثاني","activity3":"reading","skill":"الأسلوب اللغوي والتمني والترجي","passage":"«ليتَ الوقتَ يتسعُ» تمني بـ«ليت»، و«لعلَّ المطرَ ينزلُ» ترجٍّ بحسب مقامه؛ يتغير معنى الأسلوب من رغبة بعيدة أو محتملة إلى توقع مرجو. ينبغي ضبط اسم الناسخ وإيضاح غرض التعبير دون الخلط بين الأسلوبين.","q1":"ما الأداة التي تفيد التمني في المثال؟","a1":"ليت","w1":["من","في","أين"],"q2":"ما الأداة التي تفيد الترجي؟","a2":"لعل","w2":["لم","هل","لن"],"practice":"أنشئ أربع جمل للتمني والترجي وفسر تغير الدلالة حسب المقام. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 2."},{"g":9,"sem":2,"n":6,"title":"الظاهرة الإملائية — الفصل الثاني","activity3":"writing","skill":"الظاهرة الإملائية والتنوين والألف الفارقة","passage":"في «كتبوا» تأتي ألف فارقة بعد واو الجماعة في الفعل الماضي، لكنها لا تضاف إلى واو جمع المذكر السالم في «معلمو المدرسة». و«كتابًا» يحمل تنوين الفتح وفق موضع الألف في الكتابة، مع مراعاة حالات خاصة.","q1":"أين تظهر الألف الفارقة؟","a1":"بعد واو الجماعة في «كتبوا»","w1":["بعد الواو في «معلمو»","في كل جمع","بعد كل ميم"],"q2":"أي تركيب لا تُزاد فيه الألف الفارقة؟","a2":"معلمو المدرسة","w2":["ذهبوا","كتبوا","راجعوا"],"practice":"اكتب أفعالًا مع واو الجماعة وأسماء مضافة تنتهي بالواو ثم فرق الرسم. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 2."},{"g":9,"sem":2,"n":7,"title":"الرسم الكتابي — الفصل الثاني","activity3":"writing","skill":"الرسم الكتابي وضبط علامات الترقيم","passage":"تُستخدم الفاصلة بين أجزاء مترابطة من الجملة، وتوضع علامة الاستفهام بعد السؤال، والفاصلة المنقوطة قد تربط جملتين بينهما علاقة سببية. لا تكفي كثرة العلامات لتحسين النص إذا كانت لا توافق المعنى.","q1":"ما علامة نهاية سؤال مباشر؟","a1":"علامة الاستفهام","w1":["علامة التعجب دائمًا","الفاصلة","النقطتان"],"q2":"لماذا تستخدم الفاصلة المنقوطة في موضع مناسب؟","a2":"لربط جملتين بينهما صلة قوية","w2":["لإلغاء الفعل","لكتابة همزة","لإنهاء كل كلمة"],"practice":"أعد ترقيم فقرة غير مضبوطة وعلل ثلاثة مواضع للاختيار. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 2."},{"g":9,"sem":2,"n":8,"title":"التواصل الكتابي — الفصل الثاني","activity3":"writing","skill":"التواصل الكتابي وتحرير رسالة رسمية","passage":"تتكون الرسالة الرسمية من جهة مخاطبة وموضوع وطلب واضح وسبب مختصر وخاتمة مهذبة. في نموذج مستقل يطلب طالب تخصيص قاعة للمراجعة ويذكر الوقت وطريقة الاستخدام المقترحة، دون إضافة معلومات خاصة لا يحتاجها الطلب.","q1":"ما العنصر الضروري في خطاب الطلب؟","a1":"المطلوب المحدد وسببه","w1":["قصيدة طويلة","الاعتذار بلا موضوع","حذف الموعد"],"q2":"أي معلومة تفيد إدارة القاعة؟","a2":"الوقت المقترح وطريقة الاستخدام","w2":["أسرار الزملاء","عدد الرسائل الشخصية","معلومات لا علاقة لها"],"practice":"اكتب رسالة رسمية من عشرة أسطر حول مشروع مدرسي وراجع النبرة والدقة. في الصف 9 استخدم مثالًا يتناسب مع خبراتك، واستخرج سبب الإجابة.","focus":"تدريب مستقل للصف 9، مستوى تحليلي متدرج، الفصل 2."}]'::jsonb)
 AS x(g integer,sem integer,n integer,title text,activity3 text,skill text,
      passage text,q1 text,a1 text,w1 text[],q2 text,a2 text,w2 text[],
      practice text,focus text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,saved_text
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='SA' AND c.id='f42518c1-c7bd-45da-bb37-69cf9eca0a56'::uuid
    AND g.grade_number=r.g AND u.semester=r.sem
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO x_count FROM public.student_lesson_progress sp WHERE sp.lesson_id=target_id;
  IF x_count<>0 THEN RAISE EXCEPTION 'SA_G7_9_PROGRESS_PRESENT_%',r.title; END IF;
  SELECT count(*) INTO x_count FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF x_count<>0 THEN RAISE EXCEPTION 'SA_G7_9_ATTEMPTS_PRESENT_%',r.title; END IF;
  IF char_length(coalesce(saved_text,''))>=350 THEN RAISE EXCEPTION 'SA_G7_9_NOT_SHORT_%',r.title; END IF;
  SELECT count(*) INTO a_count FROM public.lesson_activities WHERE lesson_id=target_id
    AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';
  IF a_count<>3 THEN RAISE EXCEPTION 'SA_G7_9_EXPECT_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET content='ضاديوم — إثراء لغوي مستقل لطلاب الصف '||r.g::text||
   ' بالمملكة العربية السعودية، الفصل '||r.sem::text||'. موضوع تدريبي أصلي تحت عنوان مهارة عامة، لا يمثل نص درس من كتاب رسمي أو مطابقة فهرسية معتمدة.'
   ||E'\n\n'||'الهدف: '||r.focus||' أن يطبق المتعلم '||r.skill||' على مثال جديد ويعلل رأيه.'
   ||E'\n\n'||'شرح وتدريب أصلي: '||r.passage
   ||E'\n\n'||'اختبار فهم وتطبيق: '||r.q1
   ||E'\n\n'||'اختبار ثان: '||r.q2
   ||E'\n\n'||'نشاط مستقل: '||r.practice
   ||E'\n\n'||'التمايز: يقدم مثال محلول وتمارين خطوة بخطوة لمن يحتاج الدعم؛ ويقدم للمتقدمين تفسيرًا ثانيًا أو مراجعة دليل مخالف. يجب أن يراجع المعلم الاستجابات المفتوحة.'
   ||E'\n\n'||'حالة المصدر: المحتوى غير رسمي ويستلزم الرجوع إلى الكتاب الفعلي. المدخل السابق محفوظ: '||coalesce(saved_text,''),
   updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET prompt=r.q1,
   content=content||jsonb_build_object('origin','DADYOOM_SA_G7_G9_TERMS_ORIGINAL_48_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
    'notOfficialBook',true,'sourceVerification','pending','text',r.q1,
    'options',CASE ((r.n+r.sem+r.g)%4)
    WHEN 0 THEN jsonb_build_array(r.a1,r.w1[1],r.w1[2],r.w1[3])
    WHEN 1 THEN jsonb_build_array(r.w1[1],r.a1,r.w1[2],r.w1[3])
    WHEN 2 THEN jsonb_build_array(r.w1[1],r.w1[2],r.a1,r.w1[3])
    ELSE jsonb_build_array(r.w1[1],r.w1[2],r.w1[3],r.a1) END),
   answer=jsonb_build_object('correct',r.a1)
   WHERE lesson_id=target_id AND activity_order=1 AND activity_type='multiple_choice'
     AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

  UPDATE public.lesson_activities SET prompt=r.q2,
   content=content||jsonb_build_object('origin','DADYOOM_SA_G7_G9_TERMS_ORIGINAL_48_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
    'notOfficialBook',true,'sourceVerification','pending','text',r.q2,
    'options',CASE ((r.n+r.sem+r.g+1)%4)
    WHEN 0 THEN jsonb_build_array(r.a2,r.w2[1],r.w2[2],r.w2[3])
    WHEN 1 THEN jsonb_build_array(r.w2[1],r.a2,r.w2[2],r.w2[3])
    WHEN 2 THEN jsonb_build_array(r.w2[1],r.w2[2],r.a2,r.w2[3])
    ELSE jsonb_build_array(r.w2[1],r.w2[2],r.w2[3],r.a2) END),
   answer=jsonb_build_object('correct',r.a2)
   WHERE lesson_id=target_id AND activity_order=2 AND activity_type='multiple_choice'
     AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_SA_G7_G9_TERMS_ORIGINAL_48_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
      'notOfficialBook',true,'sourceVerification','pending','humanReviewRequired',true,
      'text',r.practice,'audioGenerated',false)
    WHERE lesson_id=target_id AND activity_order=3 AND activity_type=r.activity3
      AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

  SELECT count(*) INTO a_count FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_SA_G7_G9_TERMS_ORIGINAL_48_20261009';
  IF a_count<>3 THEN RAISE EXCEPTION 'SA_G7_9_INCOMPLETE_ACTIVITY_UPDATE_%',r.title; END IF;
 END LOOP;
END $dadyoom$;